def ensure_seeded(state_dir: Path) -> None:
    state_dir = Path(state_dir)
    report_file = state_dir / "workstation/backtest-report.json"
    bundles_dir = state_dir / "library/bundles"
    if report_file.is_file() and bundles_dir.is_dir() and any(bundles_dir.glob("*/strategy.json")):
        return
    payload = json.loads(gzip.decompress(base64.b64decode(SEED_GZIP_B64)))
    if not report_file.is_file():
        report_file.parent.mkdir(parents=True, exist_ok=True, mode=0o700)
        report_file.write_text(json.dumps(payload["workstation_report"], separators=(",", ":")), encoding="utf-8")
    for sha_id, spec in payload.get("library_bundles", {}).items():
        sfile = bundles_dir / sha_id / "strategy.json"
        if not sfile.is_file():
            sfile.parent.mkdir(parents=True, exist_ok=True, mode=0o700)
            sfile.write_text(json.dumps(spec, indent=2) + "\n", encoding="utf-8")
